// Macro-heavy code: an opcode table generated by a macro (enum + Display +
// FromStr + encoding), tt-munchers, counting macros, nested repetitions,
// hashmap!/btreeset! literals, a state-machine DSL, bitflags-like macro,
// and a small assembler/disassembler built on top of the generated types.
use std::collections::{BTreeSet, HashMap};
use std::fmt;
use std::str::FromStr;

macro_rules! count {
    () => { 0usize };
    ($head:tt $($tail:tt)*) => { 1usize + count!($($tail)*) };
}

macro_rules! hashmap {
    ($($k:expr => $v:expr),* $(,)?) => {{
        let mut m = HashMap::with_capacity(count!($($k)*));
        $( m.insert($k, $v); )*
        m
    }};
}

macro_rules! btreeset {
    ($($x:expr),* $(,)?) => { [$($x),*].into_iter().collect::<BTreeSet<_>>() };
}

macro_rules! opcodes {
    ($( $name:ident = $code:literal ( $($arg:ident),* ) $doc:literal ;)*) => {
        #[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, PartialOrd, Ord)]
        enum Op { $($name),* }

        impl Op {
            const ALL: [Op; count!($($name)*)] = [$(Op::$name),*];
            fn code(self) -> u8 {
                match self { $(Op::$name => $code),* }
            }
            fn from_code(c: u8) -> Option<Op> {
                match c { $($code => Some(Op::$name),)* _ => None }
            }
            fn arity(self) -> usize {
                match self { $(Op::$name => count!($($arg)*)),* }
            }
            fn arg_names(self) -> &'static [&'static str] {
                match self { $(Op::$name => &[$(stringify!($arg)),*]),* }
            }
            fn doc(self) -> &'static str {
                match self { $(Op::$name => $doc),* }
            }
        }

        impl fmt::Display for Op {
            fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
                let s = match self { $(Op::$name => stringify!($name)),* };
                f.pad(&s.to_lowercase())
            }
        }

        impl FromStr for Op {
            type Err = String;
            fn from_str(s: &str) -> Result<Op, String> {
                $( if s.eq_ignore_ascii_case(stringify!($name)) { return Ok(Op::$name); } )*
                Err(format!("unknown mnemonic `{}`", s))
            }
        }
    };
}

opcodes! {
    Nop = 0x00 () "do nothing";
    Load = 0x01 (reg, imm) "load immediate into register";
    Add = 0x02 (dst, a, b) "dst = a + b";
    Sub = 0x03 (dst, a, b) "dst = a - b";
    Mul = 0x04 (dst, a, b) "dst = a * b";
    Jnz = 0x05 (reg, target) "jump if register is non-zero";
    Print = 0x06 (reg) "print a register";
    Halt = 0xff () "stop";
}

macro_rules! bitflags_lite {
    ($vis:vis struct $name:ident: $t:ty { $(const $flag:ident = $val:expr;)* }) => {
        #[derive(Clone, Copy, PartialEq, Eq, Default)]
        $vis struct $name($t);
        #[allow(non_upper_case_globals, dead_code)]
        impl $name {
            $(const $flag: $name = $name($val);)*
            fn contains(self, o: $name) -> bool { self.0 & o.0 == o.0 }
            fn union(self, o: $name) -> $name { $name(self.0 | o.0) }
            fn names(self) -> Vec<&'static str> {
                let mut v = Vec::new();
                $( if self.contains($name::$flag) && $val != 0 { v.push(stringify!($flag)); } )*
                v
            }
        }
        impl std::ops::BitOr for $name {
            type Output = $name;
            fn bitor(self, o: $name) -> $name { self.union(o) }
        }
        impl fmt::Debug for $name {
            fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
                write!(f, "{}({})", stringify!($name), self.names().join(" | "))
            }
        }
    };
}

bitflags_lite! {
    pub struct Perm: u8 {
        const READ = 1 << 0;
        const WRITE = 1 << 1;
        const EXEC = 1 << 2;
        const ALL = 0b111;
    }
}

// state machine DSL: transitions listed as `State --event--> State`
macro_rules! state_machine {
    ($name:ident [$($state:ident),*] { $($from:ident --$ev:ident--> $to:ident),* $(,)? }) => {
        #[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
        #[allow(dead_code)]
        enum $name { $($state),* }
        impl $name {
            fn on(self, event: &str) -> Option<$name> {
                $( if self == $name::$from && event == stringify!($ev) { return Some($name::$to); } )*
                None
            }
            fn transitions() -> Vec<(&'static str, &'static str, &'static str)> {
                vec![$((stringify!($from), stringify!($ev), stringify!($to))),*]
            }
        }
    };
}

state_machine!(Door [Closed, Opened, Locked] {
    Closed --open--> Opened,
    Opened --close--> Closed,
    Closed --lock--> Locked,
    Locked --unlock--> Closed,
});

// tt-muncher: parse "key: value" pairs of different value kinds into a struct-ish list
macro_rules! config {
    (@acc [$($out:tt)*]) => { vec![$($out)*] };
    (@acc [$($out:tt)*] $k:ident : [$($v:expr),*] , $($rest:tt)*) => {
        config!(@acc [$($out)* (stringify!($k), format!("list{:?}", [$($v),*])),] $($rest)*)
    };
    (@acc [$($out:tt)*] $k:ident : $v:literal , $($rest:tt)*) => {
        config!(@acc [$($out)* (stringify!($k), format!("lit {}", $v)),] $($rest)*)
    };
    (@acc [$($out:tt)*] $k:ident : { $($inner:tt)* } , $($rest:tt)*) => {
        config!(@acc [$($out)* (stringify!($k), format!("nested {:?}", config!(@acc [] $($inner)*))),] $($rest)*)
    };
    ($($t:tt)*) => { config!(@acc [] $($t)*) };
}

macro_rules! matrix {
    ($([$($x:expr),*]),*) => { vec![$(vec![$($x as f64),*]),*] };
}

macro_rules! maxm {
    ($x:expr) => { $x };
    ($x:expr, $($rest:expr),+) => {{ let a = $x; let b = maxm!($($rest),+); if a > b { a } else { b } }};
}

macro_rules! make_getters {
    ($s:ident { $($f:ident : $t:ty),* }) => {
        #[derive(Debug, Default)]
        struct $s { $($f: $t),* }
        impl $s {
            $( fn $f(&self) -> &$t { &self.$f } )*
            fn field_names() -> &'static [&'static str] { &[$(stringify!($f)),*] }
        }
    };
}

make_getters!(Settings { width: u32, title: String, ratio: f32 });

#[derive(Debug)]
struct Instr {
    op: Op,
    args: Vec<i64>,
}

fn assemble(src: &str) -> Result<Vec<u8>, String> {
    let mut labels = HashMap::new();
    let mut instrs = Vec::new();
    // first pass: labels
    let mut addr = 0usize;
    for line in src.lines().map(|l| l.split('#').next().unwrap().trim()).filter(|l| !l.is_empty()) {
        if let Some(l) = line.strip_suffix(':') {
            labels.insert(l.to_string(), addr);
            continue;
        }
        let mut parts = line.split(|c: char| c.is_whitespace() || c == ',').filter(|s| !s.is_empty());
        let op: Op = parts.next().unwrap().parse()?;
        let args: Vec<String> = parts.map(String::from).collect();
        if args.len() != op.arity() {
            return Err(format!("{} expects {} args ({}), got {}", op, op.arity(), op.arg_names().join(", "), args.len()));
        }
        addr += 1 + args.len() * 2;
        instrs.push((op, args));
    }
    let mut out = Vec::new();
    for (op, args) in instrs {
        out.push(op.code());
        for a in args {
            let v: i64 = match a.strip_prefix('r') {
                Some(r) => r.parse().map_err(|e| format!("bad register {}: {}", a, e))?,
                None => match a.parse() {
                    Ok(n) => n,
                    Err(_) => *labels.get(&a).ok_or(format!("undefined label {}", a))? as i64,
                },
            };
            out.extend_from_slice(&(v as i16).to_le_bytes());
        }
    }
    Ok(out)
}

fn disassemble(code: &[u8]) -> Vec<Instr> {
    let mut i = 0;
    let mut out = vec![];
    while i < code.len() {
        let Some(op) = Op::from_code(code[i]) else {
            break;
        };
        let args = (0..op.arity()).map(|k| i16::from_le_bytes([code[i + 1 + 2 * k], code[i + 2 + 2 * k]]) as i64).collect();
        i += 1 + 2 * op.arity();
        out.push(Instr { op, args });
    }
    out
}

fn run(code: &[u8]) -> Vec<i64> {
    let mut regs = [0i64; 8];
    let mut pc = 0usize;
    let mut out = vec![];
    let mut steps = 0;
    while pc < code.len() && steps < 10_000 {
        steps += 1;
        let op = Op::from_code(code[pc]).expect("bad opcode");
        let a = |k: usize| i16::from_le_bytes([code[pc + 1 + 2 * k], code[pc + 2 + 2 * k]]) as i64;
        let next = pc + 1 + 2 * op.arity();
        match op {
            Op::Nop => {}
            Op::Load => regs[a(0) as usize] = a(1),
            Op::Add => regs[a(0) as usize] = regs[a(1) as usize] + regs[a(2) as usize],
            Op::Sub => regs[a(0) as usize] = regs[a(1) as usize] - regs[a(2) as usize],
            Op::Mul => regs[a(0) as usize] = regs[a(1) as usize] * regs[a(2) as usize],
            Op::Jnz => {
                if regs[a(0) as usize] != 0 {
                    pc = a(1) as usize;
                    continue;
                }
            }
            Op::Print => out.push(regs[a(0) as usize]),
            Op::Halt => break,
        }
        pc = next;
    }
    out
}

fn main() {
    println!("{} opcodes", Op::ALL.len());
    for op in Op::ALL {
        println!("{:#04x} {:<6}|{} {:?} -- {}", op.code(), op, op.arity(), op.arg_names(), op.doc());
    }
    let src = "
        # factorial of 6
        load r0, 6
        load r1, 1
        load r2, 1
    loop:
        mul r1, r1, r0
        sub r0, r0, r2
        print r1
        jnz r0, loop
        halt
    ";
    let code = assemble(src).unwrap();
    println!("{} bytes: {:02x?}", code.len(), &code[..12]);
    for ins in disassemble(&code) {
        println!("  {:>5} {:?}", ins.op, ins.args);
    }
    println!("output {:?}", run(&code));
    for bad in ["frob r1", "add r1, r2", "jnz r0, nowhere", "load rx, 1"] {
        println!("{:?} -> {:?}", bad, assemble(bad));
    }

    let m = hashmap! { "one" => 1, "two" => 2, "three" => 3, };
    let mut keys: Vec<_> = m.iter().collect();
    keys.sort_by_key(|(_, v)| **v);
    println!("{:?} cap>={}", keys, m.capacity() >= 3);
    println!("{:?} {}", btreeset![5, 1, 3, 1], count!(a b c d e));

    let p = Perm::READ | Perm::EXEC;
    println!("{:?} contains WRITE {} contains READ {} all {:?} default {:?}", p, p.contains(Perm::WRITE), p.contains(Perm::READ), Perm::ALL, Perm::default());

    let mut d = Door::Closed;
    for ev in ["open", "lock", "close", "lock", "open", "unlock", "open"] {
        match d.on(ev) {
            Some(n) => {
                println!("{:?} --{}--> {:?}", d, ev, n);
                d = n;
            }
            None => println!("{:?} ignores {}", d, ev),
        }
    }
    println!("{:?}", Door::transitions());

    let cfg = config! {
        name: "demo",
        sizes: [1, 2, 3],
        inner: { depth: 2, tags: ["a", "b"], },
        last: 4.5,
    };
    for (k, v) in &cfg {
        println!("{} = {}", k, v);
    }
    let mx = matrix!([1, 2, 3], [4, 5, 6]);
    println!("{:?} max {}", mx, maxm!(3, 9, 2, 7));
    let s = Settings { width: 80, title: "t".into(), ratio: 1.5 };
    println!("{:?} {} {} {} {:?}", s, s.width(), s.title(), s.ratio(), Settings::field_names());
    println!("{} {} {}", concat!("a", 1, 2.5, true), line!(), stringify!(x + y * 2));
    let v = [1, 5, 10, 15];
    println!("{:?}", v.iter().map(|&x| matches!(x, 1..=5 | 15 if x != 5)).collect::<Vec<_>>());
}
